-- DQ-003: Staging Structural Integrity---- Purpose:-- Validate the structural composition of the staging table.---- Expected result:-- - total columns = 859-- - sample_id columns = 1-- - expression (rs_*) columns = 604-- - mutation (mu_*) columns = 249---- This validation does not modify the data.SELECT    COUNT(*) AS total_columns,    COUNT(*) FILTER (        WHERE column_name = 'sample_id'    ) AS sample_id_columns,    COUNT(*) FILTER (        WHERE column_name LIKE 'rs_%'    ) AS expression_columns,    COUNT(*) FILTER (        WHERE column_name LIKE 'mu_%'    ) AS mutation_columnsFROM information_schema.columnsWHERE table_schema = 'staging'  AND table_name = 'brca_sample_wide';